<script setup>
import {onMounted,ref,computed} from 'vue'
import PageHeader from '../components/PageHeader.vue'
import GlassWindow from '../components/GlassWindow.vue'
import {api,session} from '../lib/api.js'
const tab=ref('credentials'),credentials=ref([]),users=ref([]),invites=ref([]),teams=ref([]),audit=ref([]),agents=ref([]),nodes=ref([]),error=ref(''),message=ref(''),formOpen=ref(false),credentialForm=ref({name:'',type:'local',username:'',password:'',visibility:'private',priority:100}),userForm=ref({email:'',password:'',role:'auditor'}),inviteForm=ref({email:'',role:'auditor',teamId:''}),inviteResult=ref(null),teamName=ref(''),enrollNode=ref(''),token=ref(null)
const me=ref(null),totpSetup=ref(null),totpCode=ref(''),disablePassword=ref(''),disableCode=ref('')
const newEmail=ref('')
const uploadingAvatar=ref(false)
const trainingSettings=ref({newHostTrainingDays:30}),trainingSaving=ref(false)
const directorySettings=ref({url:'',baseDn:'',bindCredentialId:'',nodeCredentialId:null,enabled:false,syncIntervalMinutes:60}),directoryBusy=ref(false),directoryResult=ref(null)
const origin=location.origin
const isAdmin=computed(()=>['owner','admin'].includes(session.user?.role))
async function load(){try{const requests=[api('/credentials'),api('/teams'),api('/audit'),api('/agents'),api('/nodes'),api('/settings/training')];if(isAdmin.value)requests.push(api('/settings/directory'),api('/users'),api('/invites'));const result=await Promise.all(requests);[credentials.value,teams.value,audit.value,agents.value,nodes.value,trainingSettings.value]=result;if(isAdmin.value){directorySettings.value=result[6];users.value=result[7];invites.value=result[8]}error.value=''}catch(e){error.value=e.message}}
async function saveTraining(){trainingSaving.value=true;error.value='';try{trainingSettings.value=await api('/settings/training',{method:'PATCH',body:{newHostTrainingDays:Number(trainingSettings.value.newHostTrainingDays)}});message.value='New-host training duration saved'}catch(e){error.value=e.message}finally{trainingSaving.value=false}}
async function saveDirectory(silent=false){directoryBusy.value=true;error.value='';try{directorySettings.value=await api('/settings/directory',{method:'PATCH',body:{url:directorySettings.value.url,baseDn:directorySettings.value.baseDn,bindCredentialId:directorySettings.value.bindCredentialId,nodeCredentialId:directorySettings.value.nodeCredentialId||null,enabled:directorySettings.value.enabled,syncIntervalMinutes:Number(directorySettings.value.syncIntervalMinutes)}});if(!silent)message.value='Active Directory settings saved';return true}catch(e){error.value=e.message;return false}finally{directoryBusy.value=false}}
async function testDirectory(){if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/test',{method:'POST',body:{}});message.value='Directory bind and search base validated'}catch(e){error.value=e.message}finally{directoryBusy.value=false}}
async function syncDirectoryNow(){if(!await saveDirectory(true))return;directoryBusy.value=true;error.value='';try{directoryResult.value=await api('/directory/sync',{method:'POST',body:{}});message.value=`Directory sync completed: ${directoryResult.value.created} added, ${directoryResult.value.updated} updated`;await load()}catch(e){await load();error.value=e.message}finally{directoryBusy.value=false}}
async function createCredential(){try{await api('/credentials',{method:'POST',body:credentialForm.value});formOpen.value=false;credentialForm.value={name:'',type:'local',username:'',password:'',visibility:'private',priority:100};await load()}catch(e){error.value=e.message}}
async function createUser(){try{await api('/users',{method:'POST',body:userForm.value});userForm.value={email:'',password:'',role:'auditor'};message.value='User created';await load()}catch(e){error.value=e.message}}
async function createInvite(){try{inviteResult.value=await api('/invites',{method:'POST',body:{email:inviteForm.value.email,role:inviteForm.value.role,teamId:inviteForm.value.teamId||undefined}});inviteForm.value={email:'',role:'auditor',teamId:''};message.value=inviteResult.value.delivered?'Invitation emailed':'Invitation created; copy the link below';await load()}catch(e){error.value=e.message}}
async function revokeSessions(user){try{await api(`/users/${user.id}/revoke-sessions`,{method:'POST',body:{}});message.value=`Sessions revoked for ${user.email}`;await load()}catch(e){error.value=e.message}}
async function createTeam(){try{await api('/teams',{method:'POST',body:{name:teamName.value}});teamName.value='';await load()}catch(e){error.value=e.message}}
async function createToken(){try{token.value=await api('/agents/enrollment-tokens',{method:'POST',body:{nodeId:enrollNode.value}})}catch(e){error.value=e.message}}
async function revokeAgent(agent){try{await api(`/agents/${agent.id}/revoke`,{method:'POST',body:{}});message.value='Agent certificate revoked';await load()}catch(e){error.value=e.message}}
async function beginTotp(){try{totpSetup.value=await api('/auth/totp/setup',{method:'POST',body:{}});error.value=''}catch(e){error.value=e.message}}
async function confirmTotp(){try{await api('/auth/totp/confirm',{method:'POST',body:{code:totpCode.value}});me.value=await api('/auth/me');totpSetup.value=null;totpCode.value='';message.value='Authenticator enabled'}catch(e){error.value=e.message}}
async function removeTotp(){try{await api('/auth/totp/disable',{method:'POST',body:{password:disablePassword.value,code:disableCode.value}});me.value=await api('/auth/me');disablePassword.value='';disableCode.value='';message.value='Authenticator disabled'}catch(e){error.value=e.message}}
async function uploadAvatar(event){const file=event.target.files?.[0];if(!file)return;error.value='';if(file.size>512*1024){error.value='Avatar must be under 512 KB';return}uploadingAvatar.value=true;try{const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read image'));reader.readAsDataURL(file)});await api(`/users/${session.user.id}/avatar`,{method:'PUT',body:{mimeType:file.type,base64:String(dataUrl).split(',')[1]}});me.value=await api('/auth/me');message.value='Avatar updated'}catch(e){error.value=e.message}finally{uploadingAvatar.value=false;event.target.value=''}}
async function changeEmail(){try{await api(`/users/${session.user.id}/profile`,{method:'PATCH',body:{email:newEmail.value}});message.value='Verification sent to the new address';newEmail.value=''}catch(e){error.value=e.message}}
async function resendVerification(){try{await api('/auth/email-verification/request',{method:'POST',body:{}});message.value='Verification sent to your current address'}catch(e){error.value=e.message}}
onMounted(async()=>{await load();me.value=await api('/auth/me')})
</script>
<template><div class="view"><PageHeader eyebrow="CONTROL PLANE / SETTINGS" title="Administration" description="Manage credentials, operators, teams and agent enrollment" /><div v-if="error" class="error-msg">{{error}}</div><div v-if="message" class="success-msg">{{message}}</div><div class="admin-layout"><aside class="panel glass admin-nav"><button v-for="name in ['credentials','users','teams','agents','training','directory','audit','security']" :key="name" v-show="name!=='directory'||isAdmin" :class="{active:tab===name}" @click="tab=name"><i class="mdi" :class="`mdi-${({credentials:'key-outline',users:'account-multiple-outline',teams:'account-group-outline',agents:'lan-connect',training:'brain',directory:'domain',audit:'clipboard-text-clock-outline',security:'shield-key-outline'})[name]}`"></i>{{name}}</button></aside><section class="panel glass admin-content"><template v-if="tab==='security'"><div class="panel-title"><div><span class="eyebrow">MY ACCOUNT</span><h2>Authenticator</h2></div><span class="status" :class="me?.totpEnabled?'reachable':'unknown'">{{me?.totpEnabled?'Enabled':'Disabled'}}</span></div><div class="security-settings"><p>Protect your control plane login with a 6-digit code from an authenticator app.</p><div class="avatar-setting"><img v-if="me?.profile?.avatar_url" :src="me.profile.avatar_url" alt="Your avatar" class="avatar-preview"><div v-else class="avatar-preview avatar-placeholder">{{session.user?.email?.[0]?.toUpperCase()||'W'}}</div><label>Profile image (PNG, JPEG or WebP, up to 512 KB)<input type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploadingAvatar" @change="uploadAvatar"></label></div><form class="inline-form" @submit.prevent="changeEmail"><input v-model="newEmail" type="email" required :placeholder="me?.email||'New email address'" aria-label="New email address"><button class="button small secondary">Change email</button></form><button v-if="me&&!me.emailVerified" class="button small secondary" @click="resendVerification">Resend email verification</button><template v-if="!me?.totpEnabled"><button v-if="!totpSetup" class="button primary" @click="beginTotp">Set up authenticator</button><div v-else class="form-grid"><label>Setup secret<input :value="totpSetup.secret" readonly></label><label>Authenticator URI<input :value="totpSetup.uri" readonly></label><label>Enter current code<input v-model="totpCode" inputmode="numeric" maxlength="6" placeholder="000000"></label><div class="form-actions"><button class="button primary" @click="confirmTotp">Verify and enable</button></div></div></template><div v-else class="form-grid"><label>Current password<input v-model="disablePassword" type="password"></label><label>Authenticator code<input v-model="disableCode" inputmode="numeric" maxlength="6"></label><div class="form-actions"><button class="button danger" @click="removeTotp">Disable authenticator</button></div></div></div></template><template v-else-if="tab==='training'"><div class="panel-title"><div><span class="eyebrow">HOST LIFECYCLE</span><h2>New host training</h2></div><span class="status learning">Automatic</span></div><div class="training-settings"><p>New nodes collect observed traffic before their learned allow rules are applied. A failed collection or apply stays visible for retry.</p><form class="training-settings-form" @submit.prevent="saveTraining"><label>Default training period (days)<input v-model.number="trainingSettings.newHostTrainingDays" type="number" min="1" max="365" required></label><button v-if="isAdmin" class="button primary" :disabled="trainingSaving">{{trainingSaving?'Saving…':'Save duration'}}</button></form><p class="muted">This setting applies to nodes added later. Existing training deadlines stay as scheduled. Relearning duration is set per node in Inventory.</p></div></template><template v-else-if="tab==='directory'"><div class="panel-title"><div><span class="eyebrow">INVENTORY SOURCE</span><h2>Active Directory</h2></div><span class="status" :class="directorySettings.enabled?'reachable':'unknown'">{{directorySettings.enabled?'Scheduled':'Disabled'}}</span></div><div class="directory-settings"><p>Use a read-only directory account from the credential vault to discover computer objects. LDAPS certificate validation is required. Discovered hosts enter new-host training when enabled in AD.</p><form class="directory-form" @submit.prevent="saveDirectory()"><label>LDAPS server URL<input v-model.trim="directorySettings.url" type="url" required placeholder="ldaps://dc.example.com:636/"></label><label>Search base DN<input v-model.trim="directorySettings.baseDn" required placeholder="DC=example,DC=com"></label><label>Directory bind credential<select v-model="directorySettings.bindCredentialId" required><option value="">Select vault credential</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}} · {{credential.username}}</option></select></label><label>WinRM credential for discovered nodes<select v-model="directorySettings.nodeCredentialId"><option :value="null">Assign later</option><option v-for="credential in credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><label>Sync interval (minutes)<input v-model.number="directorySettings.syncIntervalMinutes" type="number" min="5" max="1440" required></label><label class="directory-toggle"><input v-model="directorySettings.enabled" type="checkbox"> Enable scheduled inventory sync</label><div class="directory-actions"><button class="button primary" :disabled="directoryBusy">Save connection</button><button type="button" class="button secondary" :disabled="directoryBusy" @click="testDirectory">Test connection</button><button type="button" class="button secondary" :disabled="directoryBusy||!directorySettings.enabled" @click="syncDirectoryNow">Sync computers now</button></div></form><div class="directory-status"><strong>Last sync: {{directorySettings.lastSyncStatus||'Never'}}</strong><span>{{directorySettings.lastSyncedAt?new Date(directorySettings.lastSyncedAt).toLocaleString():'No successful sync yet'}} · {{directorySettings.lastSyncCount??0}} computers</span><small v-if="directorySettings.lastSyncError" class="danger-text">{{directorySettings.lastSyncError}}</small><small v-if="directoryResult?.found!==undefined">Latest run: {{directoryResult.created}} added, {{directoryResult.updated}} updated, {{directoryResult.missing}} missing from AD.</small></div><p class="muted">Directory sync never deletes a node or its policies. Trust the domain controller certificate with the server OS or NODE_EXTRA_CA_CERTS. Account control actions require separate review and are not enabled here.</p></div></template><template v-else-if="tab==='credentials'"><div class="panel-title"><div><span class="eyebrow">SECRET STORE</span><h2>Credential vault</h2></div><button class="button small primary" @click="formOpen=true"><i class="mdi mdi-plus"></i> Add credential</button></div><div class="table-wrap"><table><thead><tr><th>NAME</th><th>TYPE</th><th>USERNAME</th><th>VISIBILITY</th><th>PRIORITY</th></tr></thead><tbody><tr v-for="credential in credentials" :key="credential.id"><td><i class="mdi mdi-key-outline"></i> {{credential.name}}</td><td>{{credential.type}}</td><td class="mono">{{credential.username}}</td><td>{{credential.visibility}}</td><td>{{credential.priority}}</td></tr><tr v-if="!credentials.length"><td colspan="5" class="empty-table">No credentials stored. Add one before connecting to a node.</td></tr></tbody></table></div></template><template v-else-if="tab==='users'"><div class="panel-title"><div><span class="eyebrow">ACCESS CONTROL</span><h2>Operators</h2></div></div><div class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>STATUS</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.email}}</td><td>{{user.role}}</td><td><span class="status" :class="user.suspended?'unreachable':'reachable'">{{user.suspended?'Suspended':'Active'}}</span></td><td>{{new Date(user.created_at).toLocaleDateString()}}</td><td><button v-if="isAdmin&&user.id!==session.user?.id" class="button small secondary" @click="revokeSessions(user)">Revoke sessions</button></td></tr></tbody></table></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createUser"><input v-model="userForm.email" type="email" required placeholder="New user's email"><input v-model="userForm.password" type="password" minlength="12" required placeholder="Temporary password"><select v-model="userForm.role"><option>auditor</option><option>editor</option><option>admin</option></select><button class="button small primary">Create user</button></form><div v-if="isAdmin" class="panel-title"><div><span class="eyebrow">ONBOARDING</span><h2>Invitations</h2></div></div><form v-if="isAdmin" class="inline-form" @submit.prevent="createInvite"><input v-model="inviteForm.email" type="email" required placeholder="Invitee email"><select v-model="inviteForm.role"><option>auditor</option><option>editor</option><option>admin</option><option v-if="session.user?.role==='owner'">owner</option></select><select v-model="inviteForm.teamId"><option value="">No team</option><option v-for="team in teams" :key="team.id" :value="team.id">{{team.name}}</option></select><button class="button small primary">Invite</button></form><div v-if="inviteResult?.inviteUrl" class="code-block">{{inviteResult.inviteUrl.startsWith('http')?inviteResult.inviteUrl:origin+inviteResult.inviteUrl}}<small>Share this link with {{inviteResult.email}}. It expires in seven days.</small></div><div v-if="invites.length" class="table-wrap"><table><thead><tr><th>EMAIL</th><th>ROLE</th><th>DELIVERY</th><th>STATUS</th></tr></thead><tbody><tr v-for="invite in invites" :key="invite.id"><td>{{invite.email}}</td><td>{{invite.role}}</td><td>{{invite.delivered_at?'Emailed':'Manual link'}}</td><td>{{invite.accepted_at?'Accepted':new Date(invite.expires_at)<new Date()?'Expired':'Pending'}}</td></tr></tbody></table></div></template><template v-else-if="tab==='teams'"><div class="panel-title"><div><span class="eyebrow">ORGANIZATION</span><h2>Teams</h2></div></div><div v-for="team in teams" :key="team.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-account-group-outline"></i></div><strong>{{team.name}}</strong></div><div v-if="!teams.length" class="empty-side">No teams created.</div><form v-if="isAdmin" class="inline-form" @submit.prevent="createTeam"><input v-model="teamName" required placeholder="New team name"><button class="button small primary">Create team</button></form></template><template v-else-if="tab==='agents'"><div class="panel-title"><div><span class="eyebrow">ENDPOINT CONNECTIVITY</span><h2>Agents</h2></div></div><div v-for="agent in agents" :key="agent.id" class="segment-row"><div class="segment-icon"><i class="mdi mdi-lan-connect"></i></div><div><strong>{{nodes.find(n=>n.id===agent.node_id)?.hostname||agent.node_id}}</strong><small>{{agent.version}} · {{agent.mode}} · {{agent.last_checkin_at||'Never checked in'}} · {{agent.revoked_at?'Revoked':'Active'}}</small></div><button v-if="isAdmin&&!agent.revoked_at" class="button small danger" @click="revokeAgent(agent)">Revoke</button></div><div v-if="!agents.length" class="empty-side">No agents enrolled.</div><div v-if="isAdmin" class="inline-form"><select v-model="enrollNode"><option value="">Select node for token</option><option v-for="node in nodes" :key="node.id" :value="node.id">{{node.hostname}}</option></select><button class="button small secondary" :disabled="!enrollNode" @click="createToken">Generate token</button></div><div v-if="token" class="code-block">{{token.token}}<small>Expires {{new Date(token.expiresAt).toLocaleString()}}</small></div><p class="muted">Certificate backed enrollment and MSI distribution require Windows packaging and PKI setup.</p></template><template v-else><div class="panel-title"><div><span class="eyebrow">CHANGE HISTORY</span><h2>Audit trail</h2></div></div><div class="table-wrap"><table><thead><tr><th>TIME</th><th>ACTION</th><th>ENTITY</th><th>ACTOR</th></tr></thead><tbody><tr v-for="entry in audit" :key="entry.id"><td>{{new Date(entry.at).toLocaleString()}}</td><td class="mono">{{entry.action}}</td><td>{{entry.entity_type}} / {{entry.entity_id?.slice(0,8)}}</td><td class="mono">{{entry.actor_user_id?.slice(0,8)||'system'}}</td></tr><tr v-if="!audit.length"><td colspan="4" class="empty-table">No audited actions yet.</td></tr></tbody></table></div></template></section></div><GlassWindow v-model="formOpen" title="Add credential"><form class="form-grid" @submit.prevent="createCredential"><label>Name<input v-model="credentialForm.name" required placeholder="Domain service account"></label><label>Type<select v-model="credentialForm.type"><option value="local">Local</option><option value="domain">Domain</option></select></label><label>Username<input v-model="credentialForm.username" required placeholder="DOMAIN\service"></label><label>Password<input v-model="credentialForm.password" type="password" required autocomplete="new-password"></label><label>Visibility<select v-model="credentialForm.visibility"><option value="private">Private</option><option value="team">Team</option></select></label><label>Priority<input v-model.number="credentialForm.priority" type="number"></label><div class="form-actions"><button class="button primary">Store credential</button></div></form></GlassWindow></div></template>
